<script>
	import { API, Permission as RetainedPermission } from "$lib";
	import { page } from "$app/state";
	import { onMount } from "svelte";
	import ProtectedCondition from "$lib/components/ui/ProtectedCondition.svelte";
	import ProtectedVerified from "$lib/components/ui/ProtectedVerified.svelte";
	import { Session } from "$lib/stores";

	const { children } = $props();
	let hasOwnedStaging = $state(false);
	const Permission = { Chapter: { canCreate: () => RetainedPermission.Chapter.canCreate() || hasOwnedStaging } };
	onMount(() => {
		let disposed = false;
		void (async () => {
			if (!(await Session.isValid())) return;
			const saved = await API.UploadSession.Get();
			if (!disposed) hasOwnedStaging = saved?.status === 200 && saved.body?.manga_id === page.params.id;
		})().catch(() => { /* Existing protected UI remains conservative. */ });
		return () => { disposed = true; };
	});
</script>

<ProtectedVerified>
	<ProtectedCondition isAllowed={!!$Session && Permission.Chapter.canCreate()}>
		{@render children?.()}
	</ProtectedCondition>
</ProtectedVerified>
